def eulerian_num(n, m):
    if n == 0:
        return 1 if m == 0 else 0
    if m < 0 or m >= n:
        return 0
    row = [1]  # n = 1
    for i in range(2, n + 1):
        new = []
        for j in range(i):
            a = row[j] * (j + 1) if j < len(row) else 0
            b = row[j - 1] * (i - j) if j >= 1 else 0
            new.append(a + b)
        row = new
    return row[m]

def eulerian_num(n, m):
    if n == 0:
        return 1 if m == 0 else 0
    if m < 0 or m >= n:
        return 0
    prev = [1]  # n = 1
    for i in range(2, n + 1):
        cur = [0] * i
        for j in range(i):
            a = prev[j - 1] if 0 <= j - 1 < len(prev) else 0
            b = prev[j] if j < len(prev) else 0
            cur[j] = (i - j) * a + (j + 1) * b
        prev = cur
    return prev[m]

def eulerian_num(n, m):
    if n == 0:
        return 1 if m == 0 else 0
    if m < 0 or m >= n:
        return 0
    prev = [1]  # n = 1
    for i in range(2, n + 1):
        cur = [0] * i
        for j in range(i):
            a = prev[j - 1] if 0 <= j - 1 < len(prev) else 0
            b = prev[j] if j < len(prev) else 0
            cur[j] = (i - j) * a + (j + 1) * b
        prev = cur
    return prev[m]

