from math import gcd

def _egcd(a, b):
    if b == 0:
        return (a, 1, 0)
    g, x, y = _egcd(b, a % b)
    return (g, y, x - (a // b) * y)

def find_solution(a, b, n):
    if a > 0 and b > 0:
        i = 0
        while i * a <= n:
            if (n - i * a) % b == 0:
                return (i, (n - i * a) // b)
            i += 1
        return None
    g = gcd(a, b)
    if g == 0:
        return (0, 0) if n == 0 else None
    if n % g != 0:
        return None
    g2, x, y = _egcd(a, b)
    if g2 < 0:
        x, y = -x, -y
    k = n // g
    return (x * k, y * k)
