def get_total_number_of_sequences(m, n):
    dp = [0] + [1] * m  # length 1
    for _ in range(2, n + 1):
        prefix = [0] * (m + 1)
        for i in range(1, m + 1):
            prefix[i] = prefix[i - 1] + dp[i]
        new = [0] * (m + 1)
        for x in range(1, m + 1):
            new[x] = prefix[x // 2]
        dp = new
    return sum(dp)

