def pair_xor_Sum(arr, n):
    n = min(n, len(arr))
    total = 0
    for i in range(n):
        for j in range(i + 1, n):
            total += arr[i] ^ arr[j]
    return total

def pair_xor_Sum(arr, n):
    n = min(n, len(arr))
    total = 0
    for i in range(n):
        for j in range(i + 1, n):
            total += arr[i] ^ arr[j]
    return total

def pair_xor_Sum(arr, n):
    arr = arr[:n]
    if not arr:
        return 0
    m = max(arr).bit_length()
    total = 0
    for b in range(m):
        c = sum(1 for x in arr if (x >> b) & 1)
        total += c * (len(arr) - c) * (1 << b)
    return total

